const option=name=>process.argv.includes(name)?process.argv[process.argv.indexOf(name)+1]:null;
const checkpointDir=option('--checkpoint-dir');
function checkpoint(h,label='latest'){
 if(!checkpointDir)return;
 const directory=resolve(checkpointDir);mkdirSync(directory,{recursive:true});
 const record={provenance:{kind:'normal-public-command-checkpoint',label,seed:618033,counts:h.counts},state:h.s};
 writeFileSync(join(directory,label.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')+'.json'),JSON.stringify(record));
}
function resumeCheckpoint(){
 const path=option('--resume');if(!path)return null;
 const record=JSON.parse(readFileSync(path,'utf8'));
 assert.equal(record.provenance?.kind,'normal-public-command-checkpoint','only labeled normal-command checkpoints may resume this suite');
 return harness(S.validateSave(record.state));
}

