 // Long-term cultivation crosses genuine rain seasons. Pay for drainage through public play.
 while(h.s.ecologiesBySceneId['scene:yunxiu-courtyard'].surfaceZones['zone:yard-path'].drainage<1){h.resources({stone:12,wood:8,food:40});h.rest();const hall=h.s.buildings.find(b=>b.type==='hall'),at=buildingAccess(h.s,hall);h.walk(at.x,at.y);const r=h.act('improveDrainage');h.save();h.until(s=>!s.activitiesById[r.id],'actual drainage preparation',3000);h.save();}
 for(const type of ['granary','meditation'])if(!h.s.buildings.some(b=>b.type===type))h.build(type);if(h.s.story.step===4)h.act('advanceStory');for(const b of h.s.buildings.filter(b=>b.type==='library'&&b.enabled===false))h.act('toggleBuilding',b.id);
 if(h.s.master.realm>=10&&!h.s.buildings.some(b=>b.type==='well')){while(S.stage(h.s)<2&&h.s.disciples.length<S.capacity(h.s)){h.resources({jade:65,herb:8,food:8});h.act('recruit');h.save();}assert(S.stage(h.s)>=2,'actual five-member courtyard stage is required for the well');h.build('well');h.save();milestone(h,'real well built from resumed foundation save');}
 if(h.s.master.realm<12)h.resources({insight:30});milestone(h,'actual stored doctrine logistics to public budget');
 const study=id=>{h.resources({food:2});if(h.s.master.energy<25)h.rest();const r=h.act('masterStudy',id);h.save();h.until(s=>s.srCultivation.orders[r.orderId].phase==='completed','actual study '+id,4000);};
 if(!Object.values(h.s.srCultivation.orders).some(o=>o.kind==='foundation-source'&&o.phase==='completed')){for(let prepare=0;prepare<12;prepare++){h.resources({jade:230,herb:35,food:30});h.merchant({idle:true});if(h.s.resources.jade>=180&&h.s.resources.herb>=30&&h.s.resources.food>=8)break;}const material=h.act('reliableFoundation','commission');h.save();h.until(s=>s.srCultivation.orders[material.orderId].phase==='completed','reliable foundation commission',6000);assert.equal(h.s.stockpilesById['stockpile:carried:master'].pills.foundation,1,'commissioned concrete pill delivered to the master');assert.equal(availablePills(h.s,'person:master','foundation'),1);h.save();milestone(h,'actual reliable foundation pill commission');}
 while(h.s.master.realm<12){
  h.resources({food:40});h.rest();h.act('masterAction','cultivate');let iterations=0;
  while(h.s.master.xp<S.xpNeed(h.s.master.realm)){assert(iterations++<30,'normal cultivation bounded');h.until(s=>s.master.xp>=S.xpNeed(s.master.realm)||s.master.energy<25,'normal cultivation accumulation',9000);if(h.s.master.xp<S.xpNeed(h.s.master.realm)){h.resources({food:40});h.rest();h.act('masterAction','cultivate');}}
  if(h.s.master.realm>=9)while((h.s.master.artsById.foundation?.understanding||0)<36)study('foundation');
  h.until(s=>s.master.breakthroughCooldown<=s.time,'breakthrough recovery');for(let prepare=0;prepare<8;prepare++){h.rest();const budget=S.breakthroughCost(h.s.master);h.resources({...budget,jade:budget.jade+40,food:40});if(h.s.master.energy>=35&&Object.entries(S.breakthroughCost(h.s.master)).every(([k,v])=>h.s.resources[k]>=v))break;}const realm=h.s.master.realm,r=h.act('beginBreakthrough');if(realm===9){assert(h.s.srCultivation.orders[r.orderId].pillAllocation);assert.equal(availablePills(h.s,'person:master','foundation'),0,'reserved concrete pill cannot be spent twice');}h.save();h.until(s=>s.srCultivation.orders[r.orderId].phase==='completed','real staged breakthrough',4000);assert.equal(h.s.master.realm,realm+1);if(realm===9){const a=h.s.srCultivation.orders[r.orderId].pillAllocation;assert.equal(h.s.srEconomy.pillAllocations[a.id].phase,'consumed');assert(a.parts.some(p=>p.stockpileId==='stockpile:carried:master'));assert.equal(h.s.stockpilesById['stockpile:carried:master'].pills.foundation,0);}h.save();milestone(h,'normal breakthrough '+h.s.master.realm);if(h.s.master.realm===10&&!h.s.buildings.some(b=>b.type==='well')){h.build('well');h.save();milestone(h,'real well built at foundation');}
 }
 const sword=Object.values(h.s.itemsById).find(i=>i.definitionId==='equipment:iron-sword'&&i.ownerId==='person:master');if(sword.location?.slot!=='weapon'){const wield=h.act('equipItem',sword.id,'weapon');h.until(s=>s.srEquipment.orders[wield.orderId].phase==='completed','earned inherited sword actually equipped');h.save();}
 h.resources({jade:40,food:100,herb:20,wood:15,stone:15});h.rest();h.travel('scene:market',{cargo:{jade:35,food:80,herb:12,wood:12,stone:12},continuityLabel:'sr002-outbound'});h.worldWalk(12.5,16);h.act('srWorldCommand',{action:'investigate',sourceId:'object:market:ledger'});h.until(s=>!s.srWorld.interaction,'real ledger investigation');h.save();h.travel('scene:quarry');h.worldWalk(13.5,16);h.act('srWorldCommand',{action:'investigate',sourceId:'object:quarry:artisan'});h.until(s=>!s.srWorld.interaction,'real artisan testimony');h.save();
 return normalFinishRevenge(h);
