 test('fresh public equipment / timed equip / unique slot and save recovery',()=>{const h=harness();h.act('masterAction','heal');h.until(s=>s.master.wound===0,'healing');const item=Object.values(h.s.itemsById).find(i=>i.definitionId==='equipment:iron-sword');assert(item,'starting inheritance item');const r=h.act('equipItem',item.id,'weapon');assert.equal(h.s.itemsById[item.id].location.slot,undefined);h.save();h.until(s=>s.srEquipment.orders[r.orderId].phase==='completed','timed equip');assert.equal(h.s.itemsById[item.id].location.slot,'weapon');assert.equal(h.s.itemsById[item.id].ownerId,'person:master');assert.equal(Object.values(h.s.itemsById).filter(i=>i.location.kind==='person'&&i.location.id==='person:master'&&i.location.slot==='weapon').length,1);h.save();return {setup:'fresh initial inherited iron sword; no state injection',...h.counts};});
 test('natural rain crisis / late permanent death / knowledge stays limited / save recovery',()=>{const h=harness();h.act('masterAction','heal');h.until(s=>s.master.wound===0,'healing');h.act('advanceStory');h.until(s=>s.weatherByRegionId['region:yunxiu'].phase==='rain','ordinary weather',3000);h.act('srStoryCommand',{action:'activateRainChain'});h.until(s=>s.crisesById['crisis:rain:su-yelan']?.outcome==='dead','late death',1500);const p=h.s.personsById['person:su-yelan'];assert.equal(p.lifeStatus,'dead');assert.equal(S.viewSRCrises(h.s).known[0].outcome,null);assert(h.s.itemsById['item:relic:person:su-yelan']);h.save();h.travel('scene:valley');h.worldWalk(47,35);h.act('srCrisisCommand',{action:'search',crisisId:'crisis:rain:su-yelan'});assert.equal(S.viewSRCrises(h.s).known[0].outcome,'dead');const before=JSON.stringify(h.s);assert.throws(()=>h.act('srCrisisCommand',{action:'treat',crisisId:'crisis:rain:su-yelan'}),/复活/);assert.equal(JSON.stringify(h.s),before);h.save();return {setup:'fresh initial SR; natural weather and intentional inaction; no injection',...h.counts};});
 test('fixture combat / 100ms clock / second boundary no double advance / elapsed save recovery',()=>{const source=S.initial({sr:true,seed:618033});source.master.realm=10;source.master.wound=0;source.master.energy=100;if(!source.srWorld.knownScenes.includes('scene:qixia'))source.srWorld.knownScenes.push('scene:qixia');const h=harness(source,'fixture');h.travel('scene:qixia');h.worldWalk(32,23);h.act('srStoryCommand',{action:'challenge',personId:'person:han-lichuan'});h.save();const start=h.s.combat.elapsed,tick=h.s.worldTick;S.tick(h.s,.1);assert(Math.abs(h.s.combat.elapsed-start-.1)<1e-8);assert.equal(h.s.worldTick,tick+1);h.save();const a=S.validateSave(JSON.parse(JSON.stringify(h.s))),b=S.validateSave(JSON.parse(JSON.stringify(h.s)));S.tick(a,1);for(let n=0;n<10;n++)S.tick(b,.1);assert.equal(a.worldTick,b.worldTick);assert(Math.abs(a.combat.elapsed-b.combat.elapsed)<1e-8);assert(Math.abs(a.combat.elapsed-start-1.1)<1e-8);assert.equal(a.combat.player.hp,b.combat.player.hp);S.validateSave(a);return {setup:'explicit realm10/healthy/known qixia fixture; public travel, positioning and challenge; no normal progression claim',worldTicks:11,elapsedAdvance:1.1};});
 test('legal legacy completed save / upgrade preserves result and zero offline advance',()=>{const input=option('--legacy-save')||new URL('./acceptance-1.4.2/legacy-full.json',import.meta.url);if(!existsSync(input))return {not_run:true,setup:'Historic completed save not supplied; use --legacy-save. No QA dump is uploaded as source.'};const source=JSON.parse(readFileSync(input,'utf8')); const raw=source.state??source;const checked=Legacy.validateSave(raw),before=JSON.stringify(checked);const migrated=S.validateSave(checked,{upgrade:true});assert.equal(JSON.stringify(checked),before);assert.equal(migrated.time,checked.time);assert.equal(migrated.story.ending,'return');assert.deepEqual(migrated.story.revenge.requiredTargetIds,[]);assert.deepEqual({...migrated.resources},checked.resources);S.validateSave(JSON.parse(JSON.stringify(migrated)));return {setup:'explicit legal completed-state fixture; not a normal-play completion proof'};});
 const report={suite:'sr-public-integration',passed:results.filter(r=>r.passed).length,failed:results.filter(r=>r.passed===false).length,results,notRun:results.filter(r=>r.not_run).map(r=>r.name),notProven:['browser visual or touch experience','real device performance',...(!results.some(r=>r.passed&&r.name==='normal fresh SR growth / real investigation / three deaths / both persistent endings')?['normal-play complete revenge and foundation progress']:[]),'independent full completion of all three cultivation routes','all SR AC closure']};console.log(JSON.stringify(report,null,2));return report;
